import{_ as t,o as n,c as r,a4 as i}from"./chunks/framework.BMj-uaUw.js";const u=JSON.parse('{"title":"附录","description":"","frontmatter":{},"headers":[{"level":2,"title":"五份附录各解决什么问题","slug":"五份附录各解决什么问题","link":"#五份附录各解决什么问题","children":[{"level":3,"title":"使用建议","slug":"使用建议","link":"#使用建议","children":[]}]},{"level":2,"title":"本课程知识点与附录对照","slug":"本课程知识点与附录对照","link":"#本课程知识点与附录对照","children":[]},{"level":2,"title":"怎么用这套附录配合正文","slug":"怎么用这套附录配合正文","link":"#怎么用这套附录配合正文","children":[]}],"relativePath":"appendix/index.md","filePath":"appendix/index.md","lastUpdated":1789500889000}'),a={name:"appendix/index.md"};function d(o,e,h,s,l,g){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h1><p>这五份附录是教程的&quot;工具区&quot;。正文按顺序讲知识，附录按<strong>你此刻遇到的问题</strong>来查。</p><ul><li>写着写着忘了某个 API 怎么写 → 翻<a href="/frontend-engineering-course/appendix/cheatsheet.html">速查手册</a>。</li><li>终端报了一个看不懂的错 → 翻<a href="/frontend-engineering-course/appendix/errors.html">常见报错与排查</a>。</li><li>不确定某个包该装哪个版本、某个工具是干什么的 → 翻<a href="/frontend-engineering-course/appendix/tools.html">工具链与版本清单</a>。</li><li>要用 AI 写代码，但不确定怎么描述、怎么审 → 翻 <a href="/frontend-engineering-course/appendix/ai-tools.html">AI 编程工具速查</a>。</li><li>两个概念傻傻分不清（比如&quot;打包&quot;和&quot;编译&quot;）→ 翻<a href="/frontend-engineering-course/appendix/glossary.html">术语表</a>。</li></ul><h2 id="五份附录各解决什么问题" tabindex="-1">五份附录各解决什么问题 <a class="header-anchor" href="#五份附录各解决什么问题" aria-label="Permalink to &quot;五份附录各解决什么问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>附录</th><th>解决什么问题</th><th>什么时候翻</th></tr></thead><tbody><tr><td><a href="/frontend-engineering-course/appendix/cheatsheet.html">API 速查手册</a></td><td>记不住某个语法/函数的写法与使用场景</td><td>写代码时手边常备，按主题查</td></tr><tr><td><a href="/frontend-engineering-course/appendix/errors.html">常见报错与排查</a></td><td>遇到报错不知道从哪下手</td><td>终端或浏览器一出红字就翻</td></tr><tr><td><a href="/frontend-engineering-course/appendix/tools.html">工具链与版本清单</a></td><td>不知道要装什么、装什么版本、这个工具干什么用</td><td>配环境、新建项目、升级依赖时</td></tr><tr><td><a href="/frontend-engineering-course/appendix/glossary.html">术语表</a></td><td>概念听懂了但说不清差别，或者看文档时被术语卡住</td><td>概念混淆时，或读英文文档前</td></tr><tr><td><a href="/frontend-engineering-course/appendix/ai-tools.html">AI 编程工具速查</a></td><td>工具怎么选、提示词怎么写、AI 的代码怎么审</td><td>让 AI 写代码的前后</td></tr></tbody></table><h3 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h3><ul><li><strong>速查手册不要通读</strong>。它是字典，不是教材。写代码时遇到&quot;这个怎么拼&quot;就查一下， 几次之后自然就记住了。</li><li><strong>报错排查要按顺序做</strong>。每一条都按&quot;现象 → 原因 → 解决 → 怎么预防&quot;写， 先看现象对不对得上，再看原因，别跳过原因直接抄解决命令。 <strong>抄命令能解决一次，看懂原因能解决一类。</strong></li><li><strong>版本清单在新建项目时对照一遍</strong>。版本不对会引出一批莫名其妙的报错， 一开始就用基线版本最省事。</li><li><strong>术语表适合&quot;读文档前预习&quot;</strong>。很多英文文档读不懂不是英语问题， 是术语没对上。先在术语表里找一遍，读起来会顺很多。</li></ul><div class="tip custom-block"><p class="custom-block-title">附录也是可以提意见的</p><p>如果你遇到的报错不在<a href="/frontend-engineering-course/appendix/errors.html">常见报错</a>里， 或者某条排查步骤看完还是不懂，记下来告诉老师。 <strong>下一版的附录就靠这些反馈补全。</strong></p></div><h2 id="本课程知识点与附录对照" tabindex="-1">本课程知识点与附录对照 <a class="header-anchor" href="#本课程知识点与附录对照" aria-label="Permalink to &quot;本课程知识点与附录对照&quot;">​</a></h2><p>这张表帮你从正文跳到对应附录。左边是正文节次，右边是写代码时最可能用到的附录内容。</p><table tabindex="0"><thead><tr><th>课程内容</th><th>位置</th><th>相关附录</th></tr></thead><tbody><tr><td>工程化认知与环境搭建</td><td><a href="/frontend-engineering-course/unit01/">单元 1</a></td><td><a href="/frontend-engineering-course/appendix/tools.html">工具链清单</a>、<a href="/frontend-engineering-course/appendix/errors.html#环境类">环境类报错</a></td></tr><tr><td>Node 生态与包管理</td><td><a href="/frontend-engineering-course/unit02/">单元 2</a></td><td><a href="/frontend-engineering-course/appendix/errors.html#依赖类">依赖类报错</a>、<a href="/frontend-engineering-course/appendix/tools.html">工具链清单</a></td></tr><tr><td>package.json 与构建工具</td><td><a href="/frontend-engineering-course/unit02/03-package-json.html">单元 2.3</a>、<a href="/frontend-engineering-course/unit02/04-vite.html">2.4</a></td><td><a href="/frontend-engineering-course/appendix/glossary.html">依赖版本约定</a>、<a href="/frontend-engineering-course/appendix/errors.html#vite-与构建类">Vite 类报错</a></td></tr><tr><td>环境变量与配置</td><td><a href="/frontend-engineering-course/unit02/05-env-config.html">单元 2.5</a></td><td><a href="/frontend-engineering-course/appendix/errors.html#vite-与构建类">环境变量读到 undefined</a></td></tr><tr><td>代码规范与 Git 协作</td><td><a href="/frontend-engineering-course/unit03/">单元 3</a></td><td><a href="/frontend-engineering-course/appendix/tools.html">工具链清单</a>、<a href="/frontend-engineering-course/appendix/glossary.html">术语表</a></td></tr><tr><td>模板语法与响应式</td><td><a href="/frontend-engineering-course/unit04/">单元 4</a></td><td><a href="/frontend-engineering-course/appendix/cheatsheet.html#模板语法">模板语法速查</a>、<a href="/frontend-engineering-course/appendix/cheatsheet.html#响应式">响应式速查</a></td></tr><tr><td>计算属性与渲染控制</td><td><a href="/frontend-engineering-course/unit05/">单元 5</a></td><td><a href="/frontend-engineering-course/appendix/cheatsheet.html#响应式">响应式速查</a>、<a href="/frontend-engineering-course/appendix/errors.html#vue-运行类">Vue 运行类报错</a></td></tr><tr><td>表单绑定与生命周期</td><td><a href="/frontend-engineering-course/unit06/">单元 6</a></td><td><a href="/frontend-engineering-course/appendix/cheatsheet.html#组件">组件速查</a>、<a href="/frontend-engineering-course/appendix/cheatsheet.html#生命周期">生命周期速查</a></td></tr><tr><td>组件通信与插槽</td><td><a href="/frontend-engineering-course/unit07/">单元 7</a>、<a href="/frontend-engineering-course/unit08/">单元 8</a></td><td><a href="/frontend-engineering-course/appendix/cheatsheet.html#组件">组件速查</a></td></tr><tr><td>路由与登录鉴权</td><td><a href="/frontend-engineering-course/unit09/">单元 9</a></td><td><a href="/frontend-engineering-course/appendix/cheatsheet.html#路由">路由速查</a>、<a href="/frontend-engineering-course/appendix/errors.html#路由类">路由类报错</a></td></tr><tr><td>Pinia 与请求层</td><td><a href="/frontend-engineering-course/unit10/">单元 10</a></td><td><a href="/frontend-engineering-course/appendix/cheatsheet.html#请求">请求速查</a>、<a href="/frontend-engineering-course/appendix/errors.html#请求类">请求类报错</a></td></tr><tr><td>联调、构建优化与部署</td><td><a href="/frontend-engineering-course/unit12/">单元 12</a></td><td><a href="/frontend-engineering-course/appendix/errors.html#vite-与构建类">Vite 与构建类报错</a>、<a href="/frontend-engineering-course/appendix/tools.html">工具链清单</a></td></tr><tr><td>AI 协作（贯穿全课程）</td><td><a href="/frontend-engineering-course/guide/ai-coding.html">AI 编程导论</a></td><td><a href="/frontend-engineering-course/appendix/ai-tools.html">AI 编程工具速查</a>、<a href="/frontend-engineering-course/project/ai-collaboration.html">项目 AI 协作规范</a></td></tr><tr><td>用户端（uni-app 跨端）</td><td><a href="/frontend-engineering-course/mobile/">用户端专栏</a></td><td><a href="/frontend-engineering-course/appendix/glossary.html">跨端与小程序术语</a>、<a href="/frontend-engineering-course/appendix/tools.html#用户端专用的工具与版本">用户端版本表</a>、<a href="/frontend-engineering-course/appendix/errors.html#跨端类">跨端类报错</a></td></tr></tbody></table><h2 id="怎么用这套附录配合正文" tabindex="-1">怎么用这套附录配合正文 <a class="header-anchor" href="#怎么用这套附录配合正文" aria-label="Permalink to &quot;怎么用这套附录配合正文&quot;">​</a></h2><p>举一个真实的排查流程，你会看到附录之间怎么配合：</p><ol><li>终端报 <code>Failed to resolve import &quot;@/stores/auth&quot;</code>。</li><li>翻<a href="/frontend-engineering-course/appendix/errors.html">常见报错</a>，在&quot;Vite 与构建类&quot;里找到这一条， 按&quot;现象 → 原因&quot;定位到是<strong>路径大小写</strong>或<strong>别名没配</strong>。</li><li>按&quot;解决&quot;里的命令检查，同时去<a href="/frontend-engineering-course/appendix/tools.html">工具链清单</a>确认 Vite 版本与别名配置写法。</li><li>修好后，在<a href="/frontend-engineering-course/appendix/glossary.html">术语表</a>里确认自己理解了&quot;路径别名&quot;是什么， 下次遇到类似的报错能自己判断。</li></ol><p><strong>排查一次，把这一类问题的原因搞懂，比记住十条命令有用。</strong></p><hr><p>上一节：<a href="/frontend-engineering-course/unit12/">单元 12 · 联调优化部署与答辩</a> · 下一节：<a href="/frontend-engineering-course/appendix/cheatsheet.html">API 速查手册</a></p>',17)])])}const p=t(a,[["render",d]]);export{u as __pageData,p as default};
